using CafeStockAI.Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace CafeStockAI.Infrastructure;
public class CafeStockDbContext(DbContextOptions<CafeStockDbContext> options) : DbContext(options)
{
 public DbSet<Product> Products=>Set<Product>();public DbSet<StockArea> StockAreas=>Set<StockArea>();public DbSet<StockMovement> StockMovements=>Set<StockMovement>();
 protected override void OnModelCreating(ModelBuilder m)
 {
  m.HasDefaultSchema("cafestock");
  Root<Role>(m,"Roles");Root<Employee>(m,"Employees");Root<Branch>(m,"Branches");Root<Category>(m,"Categories");Root<Unit>(m,"Units");Root<Product>(m,"Products");Root<StockArea>(m,"StockAreas");Root<StockCount>(m,"StockCounts");Root<Transfer>(m,"Transfers");Root<StockMovement>(m,"StockMovements");Root<BusinessSettings>(m,"BusinessSettings");Root<ImportHistory>(m,"MigrationHistory");
  m.Entity<UserAccount>().ToTable("UserAccounts").HasKey(e=>e.EmployeeId);m.Entity<EmployeeBranch>().ToTable("EmployeeBranches").HasKey(e=>new{e.EmployeeId,e.BranchId});m.Entity<StockCountLine>().ToTable("StockCountLines").HasKey(e=>new{e.CountId,e.ProductId});m.Entity<TransferLine>().ToTable("TransferLines").HasKey(e=>new{e.TransferId,e.ProductId});m.Entity<ImportedLocation>().ToTable("ImportedLocations").HasKey(e=>new{e.ImportId,e.SourceWarehouseId});
  FK<Employee,Role>(m,nameof(Employee.RoleId));FK<UserAccount,Employee>(m,nameof(UserAccount.EmployeeId));FK<EmployeeBranch,Employee>(m,nameof(EmployeeBranch.EmployeeId));FK<EmployeeBranch,Branch>(m,nameof(EmployeeBranch.BranchId));FK<Product,Category>(m,nameof(Product.CategoryId));FK<Product,Unit>(m,nameof(Product.UnitId));FK<StockArea,Branch>(m,nameof(StockArea.BranchId));FK<StockCount,Branch>(m,nameof(StockCount.BranchId));FK<StockCount,Employee>(m,nameof(StockCount.SubmittedById));FK<StockCount,Employee>(m,nameof(StockCount.ReviewedById));FK<StockCountLine,StockCount>(m,nameof(StockCountLine.CountId));FK<StockCountLine,Product>(m,nameof(StockCountLine.ProductId));FK<Transfer,StockArea>(m,nameof(Transfer.SourceAreaId));FK<Transfer,StockArea>(m,nameof(Transfer.TargetAreaId));FK<Transfer,Employee>(m,nameof(Transfer.CreatedById));FK<TransferLine,Transfer>(m,nameof(TransferLine.TransferId));FK<TransferLine,Product>(m,nameof(TransferLine.ProductId));FK<StockMovement,Product>(m,nameof(StockMovement.ProductId));FK<StockMovement,StockArea>(m,nameof(StockMovement.AreaId));FK<StockMovement,Employee>(m,nameof(StockMovement.ActorId));FK<StockMovement,StockCount>(m,nameof(StockMovement.CountId));FK<StockMovement,Transfer>(m,nameof(StockMovement.TransferId));FK<ImportedLocation,ImportHistory>(m,nameof(ImportedLocation.ImportId));FK<ImportedLocation,StockArea>(m,nameof(ImportedLocation.AreaId));
  m.Entity<Role>().HasIndex(e=>e.Name).IsUnique();m.Entity<Branch>().HasIndex(e=>e.Name).IsUnique();m.Entity<Category>().HasIndex(e=>e.Name).IsUnique();m.Entity<Unit>().HasIndex(e=>e.Name).IsUnique();m.Entity<Product>().HasIndex(e=>new{e.CategoryId,e.Name}).IsUnique();m.Entity<StockArea>().HasIndex(e=>new{e.BranchId,e.Area}).IsUnique();m.Entity<UserAccount>().HasIndex(e=>e.UsernameKey).IsUnique().HasFilter("[IsEnabled] = 1");m.Entity<ImportHistory>().HasIndex(e=>e.SourceFingerprint).IsUnique();m.Entity<StockMovement>().HasIndex(e=>new{e.AreaId,e.ProductId,e.OccurredAt});
  m.Entity<StockCount>().Property(e=>e.Version).IsRowVersion();m.Entity<BusinessSettings>().Property(e=>e.Version).IsRowVersion();
  m.Entity<Product>().ToTable(t=>t.HasCheckConstraint("CK_Products_MinimumStock","[MinimumStock] >= 0"));m.Entity<StockArea>().ToTable(t=>t.HasCheckConstraint("CK_StockAreas_Kind","[Area] IN (1,2)"));m.Entity<StockCount>().ToTable(t=>t.HasCheckConstraint("CK_StockCounts_Status","[Status] IN (1,2,3)"));m.Entity<StockCountLine>().ToTable(t=>t.HasCheckConstraint("CK_StockCountLines_Quantities","[Expected] >= 0 AND [Counted] >= 0 AND ([ExpectedBar] IS NULL OR [ExpectedBar] >= 0) AND ([ExpectedDepot] IS NULL OR [ExpectedDepot] >= 0) AND ([CountedBar] IS NULL OR [CountedBar] >= 0) AND ([CountedDepot] IS NULL OR [CountedDepot] >= 0)"));m.Entity<TransferLine>().ToTable(t=>t.HasCheckConstraint("CK_TransferLines_Quantity","[Quantity] > 0"));m.Entity<Transfer>().ToTable(t=>t.HasCheckConstraint("CK_Transfers_DifferentAreas","[SourceAreaId] <> [TargetAreaId]"));
  foreach(var entity in m.Model.GetEntityTypes()) foreach(var property in entity.GetProperties())
  {
   if(property.ClrType==typeof(decimal)||property.ClrType==typeof(decimal?)){property.SetPrecision(18);property.SetScale(6);}
   if(property.ClrType==typeof(string)){property.SetMaxLength(property.Name.Contains("Note")?2000:property.Name=="Address"?500:property.Name is "PasswordHash" or "PasswordSalt"?256:property.Name=="SourceFingerprint"?64:160);property.IsNullable=false;}
  }
 }
 private static EntityTypeBuilder<T> Root<T>(ModelBuilder m,string table) where T:Entity {var e=m.Entity<T>();e.HasBaseType((Type?)null);e.ToTable(table);e.HasKey(x=>x.Id);e.Property(x=>x.Id).ValueGeneratedNever();return e;}
 private static void FK<TChild,TParent>(ModelBuilder m,string key) where TChild:class where TParent:class=>m.Entity<TChild>().HasOne<TParent>().WithMany().HasForeignKey(key).OnDelete(DeleteBehavior.Restrict);
}
